import backtrader as bt


class SmaAdxAtrStrategy(bt.Strategy):
    params = (
        ('size', 100),
    )

    def __init__(self):
        self.sma9 = bt.ind.SMA(self.data.close, period=9)
        self.sma26 = bt.ind.SMA(self.data.close, period=26)
        self.sma52 = bt.ind.SMA(self.data.close, period=52)
        self.crossover = bt.ind.CrossOver(self.sma9, self.sma26)
        self.adx = bt.ind.ADX(self.data, period=14)
        self.atr = bt.ind.ATR(self.data, period=14)

        self.order = None
        self.stop_order = None
        self.stop_price = None

    def notify_order(self, order):
        if order.status in [order.Completed, order.Canceled,
                            order.Margin, order.Rejected]:
            if order == self.order:
                self.order = None

            if order == self.stop_order:
                self.stop_order = None
                self.stop_price = None

            if order.status == order.Completed and order == self.order:
                if self.position.size > 0:
                    self.stop_price = order.executed.price - 2.0 * self.atr[0]
                    self.stop_order = self.sell(
                        size=self.position.size,
                        exectype=bt.Order.Stop,
                        price=self.stop_price
                    )
                elif self.position.size < 0:
                    self.stop_price = order.executed.price + 2.0 * self.atr[0]
                    self.stop_order = self.buy(
                        size=abs(self.position.size),
                        exectype=bt.Order.Stop,
                        price=self.stop_price
                    )

    def next(self):
        if self.order:
            return

        long_signal = (
            self.crossover[0] > 0 and
            self.data.close[0] > self.sma52[0] and
            self.adx[0] > 20
        )
        short_signal = (
            self.crossover[0] < 0 and
            self.data.close[0] < self.sma52[0] and
            self.adx[0] > 20
        )

        if self.position.size > 0:
            new_stop = self.data.close[0] - 2.0 * self.atr[0]
            if new_stop > self.stop_price:
                if self.stop_order:
                    self.cancel(self.stop_order)
                self.stop_price = new_stop
                self.stop_order = self.sell(
                    size=self.position.size,
                    exectype=bt.Order.Stop,
                    price=self.stop_price
                )

            if short_signal:
                if self.stop_order:
                    self.cancel(self.stop_order)
                    self.stop_order = None
                self.order = self.sell(size=self.position.size + self.p.size)

        elif self.position.size < 0:
            new_stop = self.data.close[0] + 2.0 * self.atr[0]
            if new_stop < self.stop_price:
                if self.stop_order:
                    self.cancel(self.stop_order)
                self.stop_price = new_stop
                self.stop_order = self.buy(
                    size=abs(self.position.size),
                    exectype=bt.Order.Stop,
                    price=self.stop_price
                )

            if long_signal:
                if self.stop_order:
                    self.cancel(self.stop_order)
                    self.stop_order = None
                self.order = self.buy(size=abs(self.position.size) + self.p.size)

        elif long_signal:
            self.order = self.buy(size=self.p.size)

        elif short_signal:
            self.order = self.sell(size=self.p.size)
